// 家紋SVGシンボルのDOM自動注入ロジック
(function() {
  function injectKamonSymbols() {
    if (typeof document === 'undefined') return;
    var content = window.KAMONS_SVG_CONTENT;
    if (!content) return;

    var mapDefs = document.getElementById('mapSvgDefs');
    if (mapDefs) {
      if (mapDefs.querySelector('symbol')) return; // 多重注入防止
      try {
        var parser = new DOMParser();
        var svgDoc = parser.parseFromString(content, 'image/svg+xml');
        var symbols = svgDoc.querySelectorAll('symbol');
        if (symbols && symbols.length > 0) {
          var frag = document.createDocumentFragment();
          for (var i = 0; i < symbols.length; i++) {
            frag.appendChild(document.importNode(symbols[i], true));
          }
          mapDefs.appendChild(frag);
          return;
        }
      } catch (e) {
        console.warn('[kamons] DOMParser injection failed, trying regex fallback:', e);
      }

      // フォールバック: <defs>...</defs> 内の文字列をinnerHTMLへ
      var m = content.match(/<defs>([\s\S]*?)<\/defs>/i);
      if (m && m[1]) {
        mapDefs.innerHTML = m[1];
        return;
      }
    }

    // mapSvgDefs が見つからない場合のフォールバック（body 直下に非表示SVGコンテナを配置）
    if (!document.getElementById('kamonsGlobalContainer') && document.body) {
      var container = document.createElement('div');
      container.id = 'kamonsGlobalContainer';
      container.style.display = 'none';
      container.innerHTML = content;
      document.body.appendChild(container);
    }
  }

  // DOMが既にパース済みなら即座に実行、まだならDOMContentLoadedで実行
  if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', injectKamonSymbols);
    } else {
      injectKamonSymbols();
    }
  }
})();
